'use strict';
const OBJECTS=[
 {id:'01-table',name:'桌面',kind:'table',focus:'布边、织纹、桌沿与中央留白',special:{key:'coverage',label:'桌布覆盖',min:60,max:90,value:78,unit:'%'}},
 {id:'02-card-front',name:'卡牌正面',kind:'front',focus:'护盾为代表卡面；短名、主体、效果区沿现版'},
 {id:'03-card-back',name:'卡背',kind:'back',focus:'共用牌背纹章，不编码隐藏卡片信息'},
 {id:'04-guardian',name:'守护法器',kind:'guardian',focus:'厚重轮廓、黄铜包边、暗红珐琅',special:{key:'progress',label:'批次进度示意',min:0,max:1,value:0,unit:'/1'}},
 {id:'05-caster',name:'施法法器',kind:'caster',focus:'细铜环、石榴红晶体与轻巧轮廓',special:{key:'progress',label:'批次进度示意',min:0,max:3,value:1,unit:'/3'}},
 {id:'06-chips',name:'筹码',kind:'chips',focus:'三类同尺寸筹码；最多5层，准确总数另显'},
 {id:'07-lamp',name:'铜灯',kind:'lamp',focus:'边缘陈设，整体可裁切；不承担游戏操作'},
 {id:'08-vial',name:'封蜡试剂瓶',kind:'vial',focus:'边缘陈设；与可用资源卡保持区别',special:{key:'fill',label:'液面造型',min:15,max:75,value:45,unit:'%'}},
 {id:'09-notes',name:'札记与笔具',kind:'notes',focus:'封面压纹与纸边；没有可读正文',special:{key:'angle',label:'摆放角度',min:-15,max:15,value:-4,unit:'°'}},
 {id:'10-light',name:'光影与反馈',kind:'light',focus:'局部布光、进度刻纹和当前目标提示',special:{key:'progress',label:'亮纹示意',min:0,max:3,value:1,unit:'/3'}}
];
const imageFile=id=>id+(id==='08-vial'?'-v02.png':'-v01.png');
const $=id=>document.getElementById(id);
const swatches='<span class="palette" aria-label="暗酒红、古金、黑褐木"><i style="background:#4a1724"></i><i style="background:#ac8c4e"></i><i style="background:#261a15"></i></span>';
function defs(){return `<svg width="0" height="0" aria-hidden="true" style="position:absolute"><defs>
<linearGradient id="brass" x2="1" y2="1"><stop stop-color="#e1c589"/><stop offset=".37" stop-color="#b29253"/><stop offset=".7" stop-color="#6d4c2b"/><stop offset="1" stop-color="#c3a167"/></linearGradient>
<linearGradient id="garnet" x2=".8" y2="1"><stop stop-color="#b87c77"/><stop offset=".35" stop-color="#723145"/><stop offset="1" stop-color="#30101d"/></linearGradient>
<pattern id="etch" width="7" height="7" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><path d="M0 0V7" stroke="#2e1920" stroke-width="1" opacity=".32"/></pattern>
<symbol id="corner" viewBox="0 0 80 80"><g fill="none" stroke="currentColor" stroke-width="1.2"><path d="M5 70V5H70M12 56V12H56M18 46Q37 43 43 18M17 17Q39 14 34 32Q17 40 17 17ZM18 46Q29 28 37 39Q43 50 27 53M46 18Q28 29 39 37Q50 43 53 27M9 64Q33 64 45 45Q64 33 64 9"/><path d="m49 49 8-8 8 8-8 8Z"/><circle cx="12" cy="12" r="3" fill="currentColor"/><circle cx="61" cy="12" r="2" fill="currentColor"/><circle cx="12" cy="61" r="2" fill="currentColor"/></g></symbol>
<symbol id="seal" viewBox="0 0 200 260"><g fill="none" stroke="currentColor"><circle cx="100" cy="130" r="61" stroke-width="1.5" stroke-dasharray="145 12 48 12"/><circle cx="100" cy="130" r="51" stroke-width=".8"/><circle cx="100" cy="130" r="70" stroke-dasharray="2 6"/><path d="M100 54 143 130 100 206 57 130Z" stroke-width="1.6"/><path d="M100 81 124 130 100 179 76 130ZM100 81V179M76 130H124"/><path d="M100 21V44M100 216V239M21 130H36M164 130H179M44 42Q20 39 31 68Q13 92 31 105M156 42Q180 39 169 68Q187 92 169 105M44 218Q20 221 31 192Q13 168 31 155M156 218Q180 221 169 192Q187 168 169 155M56 21Q100 47 144 21M56 239Q100 213 144 239" stroke-width="1"/><path d="m100 15 6 8-6 8-6-8Zm0 214 6 8-6 8-6-8Z" fill="currentColor"/></g></symbol>
<symbol id="shield-art" viewBox="0 0 200 230"><g fill="none" stroke="#9f824e" stroke-width=".8"><circle cx="100" cy="117" r="78"/><circle cx="100" cy="117" r="86" stroke-dasharray="2 7"/><path d="M27 72 18 84 26 94M173 72 182 84 174 94M58 25 62 35M142 25 138 35"/></g><path d="M43 48Q100 25 157 48L148 124Q135 173 100 205Q65 173 52 124Z" fill="url(#brass)" stroke="#533c29" stroke-width="3"/><path d="M55 56Q100 39 145 56L137 120Q126 158 100 188Q74 158 63 120Z" fill="#5a1f30" stroke="#dcc389" stroke-width="2"/><path d="M55 56Q100 39 145 56L137 120Q126 158 100 188Q74 158 63 120Z" fill="url(#etch)"/><path d="M100 44V185M62 92H139" stroke="#ba9559" stroke-width="4"/><path d="M100 69 122 102 100 147 78 102Z" fill="#e4cca0" stroke="#755032" stroke-width="2"/><path d="M100 69V147M78 102H122" stroke="#97623f"/><g class="object-engraving" fill="none" stroke="#d6b876" stroke-width=".8"><path d="M58 68 68 70 73 83M142 68 132 70 127 83M71 130 78 141 86 144M129 130 122 141 114 144"/><circle cx="100" cy="58" r="3"/></g></symbol>
<clipPath id="bottle-clip"><path d="M114 72H186V126Q221 145 220 186L210 288Q207 311 150 314Q93 311 90 288L80 186Q79 145 114 126Z"/></clipPath>
</defs></svg>`;}
const corner=()=>'<svg class="card-corner ornament" viewBox="0 0 80 80" aria-hidden="true"><use href="#corner"/></svg><svg class="card-corner bottom ornament" viewBox="0 0 80 80" aria-hidden="true"><use href="#corner"/></svg>';
function card(front=true){return front?`<button class="playing-card native-object" id="sample-card" aria-label="查看简易护盾详情"><span class="type">■</span>${corner()}<span class="title">护盾</span><svg class="face-art" viewBox="0 0 200 230" aria-hidden="true"><use href="#shield-art"/></svg><span class="effect" aria-label="护甲增加4">◇ +4</span><span class="after" aria-label="成功后施法次数增加1">✦ +1</span></button>`:`<button class="playing-card card-back native-object" id="sample-card" aria-label="翻转示例牌背"><span class="back-strip ornament"></span>${corner()}<svg class="back-seal" viewBox="0 0 200 260" aria-hidden="true"><use href="#seal"/></svg></button>`;}
function artifact(kind){let art=kind==='guardian'?`<svg viewBox="0 0 300 320" aria-hidden="true"><ellipse cx="150" cy="38" rx="21" ry="24" fill="none" stroke="url(#brass)" stroke-width="9"/><path d="M150 49 237 105 220 226 150 286 80 226 63 105Z" fill="url(#brass)" stroke="#3d291d" stroke-width="5"/><path d="M150 68 215 113 200 213 150 261 100 213 85 113Z" fill="#4a1724" stroke="#d8bb7d" stroke-width="3"/><path d="M150 68 215 113 200 213 150 261 100 213 85 113Z" fill="url(#etch)"/><path d="M150 95 188 151 150 228 112 151Z" fill="#c4a66c" stroke="#f0dca9" stroke-width="2"/><path d="M150 95V228M112 151H188" stroke="#6a3e2e" stroke-width="3"/><g class="object-engraving" fill="none" stroke="#ddbc79" stroke-width="1.4"><path d="M93 123 108 114M207 123 192 114M100 192 111 208 125 217M200 192 189 208 175 217M121 85 150 99 179 85"/><circle cx="150" cy="249" r="4"/></g></svg>`:`<svg viewBox="0 0 300 320" aria-hidden="true"><ellipse cx="150" cy="164" rx="89" ry="109" fill="none" stroke="#725134" stroke-width="9"/><ellipse cx="150" cy="161" rx="89" ry="109" fill="none" stroke="url(#brass)" stroke-width="6"/><ellipse cx="150" cy="161" rx="66" ry="82" fill="none" stroke="#c4a56a" stroke-width="2"/><path d="M150 28 196 130 150 286 104 130Z" fill="url(#garnet)" stroke="#dec89b" stroke-width="2"/><path d="M150 28V286M104 130H196M150 28 129 130 150 286 172 130Z" fill="none" stroke="#d3a8a3" stroke-width="1.5"/><path d="M150 9V31M150 283V309M47 161H78M222 161H253" stroke="url(#brass)" stroke-width="7"/><g fill="#bd9e5f" stroke="#5f4029" stroke-width="2"><path d="m150 5 9 12-9 12-9-12Zm0 285 9 12-9 12-9-12Z"/><circle cx="48" cy="161" r="6"/><circle cx="252" cy="161" r="6"/></g><g class="object-engraving" fill="none" stroke="#d7bb7c" stroke-width="1"><path d="m96 75 8 3m-20 13 8 4m112-20-8 3m20 13-8 4M96 247l8-3m-20-13 8-4m112 20-8-3m20-13-8-4"/></g></svg>`;return `<button class="artifact-object native-object" id="sample-artifact" aria-label="查看法器详情">${art}<div class="progress-dots" aria-label="批次进度示意"></div><span class="artifact-read"></span></button>`;}
function lamp(){return `<svg class="prop-svg native-object" viewBox="0 0 340 370" aria-label="独立铜灯造型"><ellipse cx="170" cy="240" rx="103" ry="91" fill="#261714" opacity=".35"/><path d="M75 226Q12 210 22 266Q35 308 86 266" fill="none" stroke="#634029" stroke-width="22"/><path d="M75 220Q14 205 25 261Q39 297 87 260" fill="none" stroke="url(#brass)" stroke-width="13"/><path d="M140 174 148 91Q170 74 193 91L201 174Z" fill="url(#brass)" stroke="#4b2f21" stroke-width="3"/><ellipse cx="170" cy="232" rx="94" ry="86" fill="url(#brass)" stroke="#38251b" stroke-width="4"/><ellipse cx="170" cy="223" rx="77" ry="68" fill="#6b332e" stroke="#d8b673" stroke-width="3"/><ellipse cx="170" cy="223" rx="62" ry="53" fill="#7b603d" stroke="#bd9c61"/><ellipse cx="170" cy="222" rx="24" ry="19" fill="#31251c" stroke="#bc9a5e" stroke-width="5"/><g class="object-engraving" fill="none" stroke="#e2bd78" stroke-width="1.4"><path d="M103 205Q119 159 153 164M237 205Q221 159 187 164M108 254Q124 280 150 281M232 254Q216 280 190 281"/><path d="m170 170 9 10-9 10-9-10Z"/></g><path class="lamp-flame" d="M170 32Q195 61 182 88Q170 102 158 88Q144 68 170 32Z" fill="#e3ad55" stroke="#f2d49a" stroke-width="2"/><path class="lamp-flame" d="M170 58Q182 79 170 91Q158 80 170 58Z" fill="#fff0bd"/></svg>`;}
function vial(){return `<svg class="prop-svg native-object" viewBox="0 0 300 370" aria-label="独立封蜡试剂瓶造型"><path d="M114 72H186V126Q221 145 220 186L210 288Q207 311 150 314Q93 311 90 288L80 186Q79 145 114 126Z" fill="#c7bda620" stroke="#d1c6a1" stroke-width="2"/><g clip-path="url(#bottle-clip)"><rect class="vial-liquid" x="70" y="215" width="160" height="100" fill="url(#garnet)" opacity=".9"/><path d="M85 252Q150 233 215 252M87 267Q150 248 213 267" fill="none" stroke="#cb898755" stroke-width="2"/></g><path d="M105 83H195V105H105Z" fill="url(#brass)" stroke="#573d28" stroke-width="2"/><path d="M117 44H183V81H117Z" fill="#76543b" stroke="#b99a68" stroke-width="2"/><path d="M126 47V76M137 47V76M151 47V76M165 47V76M176 47V76" stroke="#402f2255"/><path d="M110 150Q91 170 96 202L103 273" fill="none" stroke="#f4dfb0" stroke-width="5" opacity=".65"/><path d="M190 164Q205 181 199 237" fill="none" stroke="#e8d8ba" stroke-width="2" opacity=".5"/><path d="M158 99Q188 122 183 159" stroke="#a5894e" stroke-width="3" fill="none"/><circle cx="185" cy="159" r="22" fill="#5c1d2a" stroke="#8c4a4c" stroke-width="3"/><g class="object-engraving" fill="none" stroke="#b88263"><circle cx="185" cy="159" r="13"/><path d="m185 148 7 11-7 11-7-11Z"/></g></svg>`;}
function notebook(){return `<svg class="prop-svg native-object notebook" viewBox="0 0 360 370" aria-label="独立札记与笔具造型"><path d="M62 59H251V305H62Z" fill="#bfae8b" stroke="#57412f" stroke-width="3"/><path d="M68 286H247M67 293H248M69 300H247" stroke="#72573c"/><path d="M54 44H248V285H54Q43 282 43 270V60Q44 46 54 44Z" fill="#2b1a18" stroke="#8d6543" stroke-width="3"/><path d="M58 44V285" stroke="#69412f" stroke-width="4"/><path d="M66 57H234V270H66Z" fill="none" stroke="#a0824f" stroke-width="1.2"/><path d="M195 44H248V100Q214 90 195 44Z" fill="#591d2b" stroke="#8c4b49"/><svg class="ornament" x="93" y="83" width="116" height="154" viewBox="0 0 200 260" color="#b28d50"><use href="#seal"/></svg><g transform="rotate(13 295 188)"><path d="M288 84H302V250H288Z" fill="#4d2a23" stroke="#b09359" stroke-width="2"/><path d="M288 240H302L307 267 295 293 283 267Z" fill="url(#brass)" stroke="#62422c" stroke-width="2"/><path d="M295 256V290" stroke="#3c2820"/><circle cx="295" cy="256" r="2" fill="#3c2820"/><path d="M288 80Q295 71 302 80V99H288Z" fill="url(#brass)"/></g></svg>`;}
function lightStudy(){return `<div class="light-field native-object"><svg viewBox="0 0 560 350" aria-label="局部进度亮纹与当前目标提示"><g transform="translate(245 175) rotate(-90)" fill="none" stroke-width="4"><path data-segment="0" d="M60 0A60 60 0 0 1 -23 55" stroke="#aa854b55"/><path data-segment="1" d="M-30 52A60 60 0 0 1 -37 -47" stroke="#aa854b55"/><path data-segment="2" d="M-30 -52A60 60 0 0 1 60 -8" stroke="#aa854b55"/></g><circle class="ornament" cx="245" cy="175" r="71" fill="none" stroke="#b3995755" stroke-width="1" stroke-dasharray="2 7"/><path class="light-marker" d="m365 161 12 14-12 14-12-14Z" fill="#b99a5b" stroke="#e1c486"/><path d="m245 154 13 21-13 21-13-21Z" fill="none" stroke="#c19a5866"/></svg></div>`;}
function chips(){const values=[Number($('life-value')?.value??60),Number($('armor-value')?.value??8),Number($('spell-value')?.value??5)];const defs=[['生命','♥','#5b2030',null],['护甲','◇','#4c5960',null],['施法次数','✦','#8b713f',null]];return '<div class="chip-set native-object">'+defs.map(([name,symbol,color,max],i)=>{const v=Math.max(0,Math.floor(Number.isFinite(values[i])?values[i]:0)),layers=v===0?0:Math.min(5,Math.ceil(Math.log2(v+1)));return `<div class="chip-item" aria-label="${name} ${v}${max?'，示例上限'+max:''}"><div class="chip-stack ${layers?'':'zero-stack'}" aria-hidden="true">${layers?Array.from({length:layers},(_,j)=>`<i class="chip-coin" data-symbol="${j===layers-1?symbol:''}" style="--layer:${j};--inlay:${color}"></i>`).join(''):symbol}</div><div class="chip-stat">${v}${max?`<small> / ${max}</small>`:''}</div></div>`;}).join('')+'</div>';}
function table(){return '<div class="sample-table native-object"><div class="cloth">'+Array.from({length:4},()=>'<svg class="corner ornament" viewBox="0 0 80 80" aria-hidden="true"><use href="#corner"/></svg>').join('')+'</div></div>';}
function renderObject(item){const renders={table,front:()=>card(true),back:()=>card(!backFacing),guardian:()=>artifact('guardian'),caster:()=>artifact('caster'),chips,lamp,vial,notes:notebook,light:lightStudy};$('native').innerHTML=renders[item.kind]();updateParameters();$('sample-artifact')?.addEventListener('click',showDetails);if($('sample-card'))$('sample-card').addEventListener('click',()=>item.kind==='back'?flip():showDetails());}
function range(key,label,min,max,value,unit){return `<div class="control-row"><label class="control-label" for="${key}">${label}<output id="${key}-out">${value}${unit}</output></label><input id="${key}" type="range" min="${min}" max="${max}" value="${value}" data-unit="${unit}"></div>`;}
let current,backFacing=true,toastTimer,pulseTimer;
function updateParameters(){if(!current)return;const n=$('native');n.style.setProperty('--zoom',Number($('scale').value)/100);n.style.setProperty('--ornament',Number($('ornament').value)/100);n.style.setProperty('--illumination',.75+Number($('light').value)/200);for(const input of document.querySelectorAll('input[type=range]')){const out=$(input.id+'-out');if(out)out.textContent=input.value+input.dataset.unit;}
if($('coverage'))n.style.setProperty('--coverage',$('coverage').value+'%');if($('angle'))n.style.setProperty('--angle',$('angle').value+'deg');if($('fill')){const amount=Number($('fill').value);document.querySelector('.vial-liquid')?.setAttribute('y',314-amount*2.4);document.querySelector('.vial-liquid')?.setAttribute('height',amount*2.4);}
if($('progress')){const v=Number($('progress').value),max=Number($('progress').max);const dots=document.querySelector('.progress-dots');if(dots){dots.innerHTML=Array.from({length:max},(_,i)=>`<i class="${i<v?'on':''}"></i>`).join('');dots.setAttribute('aria-label',`批次进度示意 ${v}/${max}`);document.querySelector('.artifact-read').textContent=v+' / '+max;}document.querySelectorAll('[data-segment]').forEach(p=>p.classList.toggle('active-segment',Number(p.dataset.segment)<v));}
const field=document.querySelector('.light-field');if(field){const dir=$('direction').value;field.style.setProperty('--light-x',dir==='left'?'20%':dir==='right'?'85%':'50%');field.style.setProperty('--light-y',dir==='center'?'50%':'15%');}}
function flip(){backFacing=!backFacing;renderObject(current);$('flip').textContent=backFacing?'翻至正面':'翻回牌背';}
function showDetails(){const content=current.kind==='front'||current.kind==='back'?'<h2>简易护盾</h2><p>对存活的玩家自身获得4点护甲。防护步骤成功且战斗未终局，随后增加1次施法次数。</p><p class="small">守护护符 · 零材料 · 每批1张 · D1</p>':`<h2>${current.kind==='guardian'?'守护护符':'施法护符'}</h2><p>${current.kind==='guardian'?'厚重护符的独立造型与D1进度示意。':'细环水晶的独立造型与D3进度示意。'}</p><p class="small">此页只审材质、尺寸与反馈，不运行生产或战斗。</p>`;$('detail-body').innerHTML=content;$('detail').showModal();}
function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,2200);}
function storageGet(key){try{return localStorage.getItem(key);}catch{return null;}}
function saveNote(){const key='yanzhou-objects-01:'+current.id;try{localStorage.setItem(key,JSON.stringify({id:current.id,name:current.name,note:$('note').value,parameters:parameters(),updatedAt:new Date().toISOString()}));$('saved').textContent='已保存在本机';}catch{$('saved').textContent='本机保存不可用，请导出批注';}}
function parameters(){const result={};document.querySelectorAll('.native-controls input,.native-controls select').forEach(e=>result[e.id]=e.value);return result;}
function downloadNotes(){const notes=OBJECTS.map(item=>{try{return JSON.parse(storageGet('yanzhou-objects-01:'+item.id)||'null');}catch{return null;}}).filter(Boolean);if(current){const i=notes.findIndex(x=>x.id===current.id),live={id:current.id,name:current.name,note:$('note').value,parameters:parameters(),updatedAt:new Date().toISOString()};if(i<0)notes.push(live);else notes[i]=live;}const url=URL.createObjectURL(new Blob([JSON.stringify({version:'BURGUNDY-OBJECTS-01',scope:'对象审核意见，不自动组装或采纳',notes},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='yanzhou-object-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function initCatalog(){document.querySelector('header').innerHTML=`<a class="wordmark" href="index.html">言咒</a><span class="crumb">对象审阅 · 01</span><div class="head-right">${swatches}<span class="badge">逐项审核后组装</span></div>`;$('catalog-grid').innerHTML=OBJECTS.map((item,i)=>`<a class="object-tile" href="${item.id}.html"><div class="tile-image"><img src="../images/${imageFile(item.id)}" alt="${item.name}效果图" loading="${i<5?'eager':'lazy'}"></div><div class="tile-meta"><span class="tile-num">${String(i+1).padStart(2,'0')}</span><h2>${item.name}</h2><small>HTML＋图</small></div></a>`).join('');$('export-all').addEventListener('click',downloadNotes);}
function initReview(){current=OBJECTS.find(x=>x.id===document.body.dataset.object);if(!current)return;const index=OBJECTS.indexOf(current),special=current.special;document.title=current.name+' · 言咒独立审阅';document.querySelector('header').innerHTML=`<a class="wordmark" href="index.html">言咒</a><a class="crumb" href="index.html">← 全部对象</a><div class="head-right">${swatches}<span class="badge">待审阅 · 不组装</span></div>`;$('object-number').textContent=String(index+1).padStart(2,'0')+' / 10';$('object-title').textContent=current.name;$('focus').textContent=current.focus;$('effect-image').src='../images/'+imageFile(current.id);$('effect-image').alt=current.name+'生成效果图';$('image-link').href='../images/'+imageFile(current.id);
$('native-controls').innerHTML=range('scale','尺寸',60,120,100,'%')+range('ornament','边饰强度',0,100,65,'%')+range('light','光照',0,100,60,'%')+(special?range(special.key,special.label,special.min,special.max,special.value,special.unit):'')+(current.kind==='chips'?'<div class="number-fields"><label>生命示例<input id="life-value" type="number" min="0" value="60"></label><label>护甲示例<input id="armor-value" type="number" min="0" value="8"></label><label>施法示例<input id="spell-value" type="number" min="0" value="5"></label></div>':'')+(current.kind==='light'?'<div class="control-row"><label class="control-label" for="direction">光线方向</label><select id="direction"><option value="left">左上</option><option value="right">右上</option><option value="center">中心柔光</option></select></div>':'');
$('object-actions').innerHTML=(current.kind==='front'||current.kind==='guardian'||current.kind==='caster'?'<button id="details">查看详情</button>':'')+(current.kind==='back'?'<button id="flip">翻至正面</button>':'')+(current.kind==='lamp'?'<button id="motion" aria-pressed="false">灯火微动</button>':'')+(current.kind==='light'?'<button id="pulse">播放一次反馈</button>':'');
$('item-nav').innerHTML=`${index?`<a href="${OBJECTS[index-1].id}.html">← 上一项</a>`:'<span></span>'}${index<9?`<a href="${OBJECTS[index+1].id}.html">下一项 →</a>`:'<a href="index.html">返回目录 →</a>'}`;document.body.insertAdjacentHTML('beforeend',defs());renderObject(current);
document.querySelectorAll('input[type=range],#direction').forEach(e=>e.addEventListener('input',updateParameters));document.querySelectorAll('.number-fields input').forEach(e=>e.addEventListener('input',()=>{if(e.value==='')return;let value=Math.max(0,Math.floor(Number(e.value)));if(!Number.isFinite(value))value=0;if(e.max)value=Math.min(value,Number(e.max));e.value=value;renderObject(current);}));
document.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>{const raster=button.dataset.mode==='raster';document.body.classList.toggle('mode-raster',raster);$('native').hidden=raster;$('raster').hidden=!raster;$('native-controls').inert=raster;$('reset-parameters').disabled=raster;document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-selected',String(b===button)));$('stage-mark').textContent=raster?'效果图 · 原图':'HTML · 可调样稿';}));$('background').addEventListener('change',e=>$('stage').dataset.background=e.target.value);
$('details')?.addEventListener('click',showDetails);$('flip')?.addEventListener('click',flip);$('motion')?.addEventListener('click',()=>{const active=$('native').classList.toggle('motion');$('motion').setAttribute('aria-pressed',String(active));$('motion').textContent=active?'停止微动':'灯火微动';});$('pulse')?.addEventListener('click',()=>{clearTimeout(pulseTimer);$('native').classList.remove('pulse');requestAnimationFrame(()=>{$('native').classList.add('pulse');pulseTimer=setTimeout(()=>$('native').classList.remove('pulse'),2700);});});
$('close-detail').addEventListener('click',()=>$('detail').close());$('note').addEventListener('input',saveNote);$('save-note').addEventListener('click',saveNote);$('export-note').addEventListener('click',downloadNotes);$('reset-parameters').addEventListener('click',()=>{document.querySelectorAll('.native-controls input').forEach(e=>e.value=e.defaultValue);if($('direction'))$('direction').value='left';renderObject(current);toast('参数已重置；批注保留');});
try{const saved=JSON.parse(storageGet('yanzhou-objects-01:'+current.id)||'null');if(saved){$('note').value=saved.note||'';for(const [id,value] of Object.entries(saved.parameters||{})){const e=$(id);if(e&&e.closest('.native-controls'))e.value=value;}renderObject(current);$('saved').textContent='已恢复本机批注与参数';}}catch{}
}
document.body.dataset.page==='catalog'?initCatalog():initReview();
